            "occurrence": 1
          }
        ]
      },
      "object": {
        "value": "Lumen Works",
        "evidence": [
          {
            "segment": "text",
            "quote": "Lumen Works",
            "occurrence": 1
          }
        ]
      }
    }
  ]
}


